#pragma once

#include "msxgl.h"

// Number of tiles loaded from the tileset (indices 0..212). The tileset
// header generated by MSXimg (--tilesUnique) holds 256 tiles in source order;
// the blank tail (213..255) is not loaded. Part of it is used by the sky
// animation, whose patterns are written at run time (see sky.h).
#define TILES_COUNT 213

// The wave animation tiles (see map_water_anim). Their sky is cyan, except in
// the bottom third of the screen, where tiles_init() turns it black for the
// title. The game only shows waves in the middle third, recoloured by the sky.
#define TILES_WAVE_FIRST    0xA5
#define TILES_WAVE_COUNT    32

#define TILES_MAKE_ADDRESS(X, Y, BASE)          ( (X) + (Y)*32 + (BASE) )
#define TILES_PUT_BUFFER(X, Y, BUFFER, SIZE)    VDP_WriteVRAM_16K((const u8*)(BUFFER), g_ScreenLayoutLow + (Y)*32 + (X), (SIZE))
#define TILES_FILL(X, Y, VALUE, SIZE)           VDP_FillVRAM_16K((VALUE), g_ScreenLayoutLow + (Y)*32 + (X), (SIZE))
#define TILES_PUT_BUFFER_CENTERED(Y, BUFFER)    TILES_PUT_BUFFER(16 - sizeof(BUFFER)/2, Y, BUFFER, sizeof(BUFFER))

// Screen 2 has one pattern/colour bank per screen third (8 rows each).
#define TILES_BANK_SIZE     0x800
#define TILES_BANK_TOP      0
#define TILES_BANK_MIDDLE   1
#define TILES_BANK_BOTTOM   2

void tiles_init(void);

// Rewrite the colours of `count` tiles from `first` in one screen third: colour
// `from` becomes `to` (foreground and background) in the tileset's colours.
// Tiles without `from` are written back unchanged.
void tiles_replace_color(u8 first, u8 count, u8 bank, u8 from, u8 to);

// Set the border/backdrop colour (R#7 low nibble). The text colour (high
// nibble) is unused in Screen 2, so it is fixed to black.
void tiles_set_border(u8 border);
